'use strict';
const INTELLIGENCE_UI13={uxAreas11,careerPersonUI12,showDigest6,digestDestination6,rivalDetail5,managementView,bind,render};
function intelligenceHome13(){show(`<h2>Kalendář a zkušenosti firmy</h2><p>Plánuj skutečné kroky na konkrétní týden a podívej se, z čeho se vedení poučilo.</p><div class="actions"><button class="primary" id="calendarNew13">Naplánovat akci</button><button class="soft" id="intelligencePeople13">Dohody s lidmi</button></div>${calendarWarnings13().map(t=>`<p class="warning">${esc(t)}</p>`).join('')}<h3>Firemní kalendář</h3>${state.intelligence13.calendar.slice().sort((a,b)=>a.due-b.due).map(x=>`<article class="news intelligence-row13"><div><strong>T${x.due} · ${esc(x.title)}</strong><p>${({planned:'Naplánováno',blocked:'Pozastaveno',executed:'Provedeno',cancelled:'Zrušeno'})[x.status]} · limit ${money(x.cap)} · rezerva ${x.reserve} týdnů</p>${x.result?`<p>${esc(x.result.text)}</p>`:''}</div>${['planned','blocked'].includes(x.status)?`<button class="soft" data-calendar-cancel13="${x.id}">Zrušit plán</button>`:''}</article>`).join('')||empty('Zatím žádná naplánovaná akce.')}<h3>Zkušenosti manažerů</h3>${staffAssignments().map(a=>{const cities=[...new Set(state.intelligence13.learning.filter(x=>x.pid===a.person.pid).map(x=>x.city))];return cities.map(city=>{const lesson=managerLesson13(a.person.pid,city);return `<article class="card"><strong>${esc(a.person.name)} · ${esc(city)}</strong><p>${lesson.samples} srovnatelných zdražení; ${lesson.harmful} s nižším výsledkem i obsluhou. ${lesson.penalty?'Další +5 Kč posuzuje s korekcí '+money(lesson.penalty)+'.':'Na změnu strategie zatím není dost podkladů.'}</p></article>`;}).join('');}).join('')||empty('Zkušenosti vznikají až po skutečných rozhodnutích a uzavřených týdnech.')}<details><summary>Doložená zdražení a výsledky</summary><div class="table-scroll"><table><thead><tr><th>Týden / manažer</th><th>Před</th><th>Po</th><th>Podklad</th></tr></thead><tbody>${state.intelligence13.learning.slice().reverse().map(x=>`<tr><td>T${x.week} · ${esc(x.name)}</td><td>${money(x.before.profit)} · ${x.before.served} hostů</td><td>${x.result?money(x.result.profit)+' · '+x.result.served+' hostů':'Čeká na týden'}</td><td>${x.result?.comparable?'Srovnatelný provoz':'Změnily se podmínky / nedostatek kávy'}</td></tr>`).join('')}</tbody></table></div></details><p class="sub">Paměť nepřidává dovednosti ani peníze. Srovnání není důkazem, že změnu výsledku způsobila jen cena. Mandát, rezervy a schvalování pokračují.</p>`);el('calendarNew13').onclick=calendarNewUI13;el('intelligencePeople13').onclick=careerDirectory12;on('[data-calendar-cancel13]',b=>{const id=b.dataset.calendarCancel13;experienceConfirmation12('Zrušit naplánovanou akci?','Dosud neprovedená akce se zruší bez platby.',()=>cancelSchedule13(id),intelligenceHome13,'Zrušit plán');el('cancelAction').onclick=intelligenceHome13;});}
function calendarNewUI13(){const stores=state.stores.filter(s=>!s.franchise),locations=LOCATIONS.filter(l=>unlocked(l.city)&&!owned(l.id)&&!occupant(l.id)),products=state.products6.catalog.filter(p=>p.status==='released');show(`<h2>Naplánovat firemní akci</h2><p>Provede se na začátku zvoleného týdne při jeho odehrání. Při chybějících penězích, lidech nebo zásobách se pozastaví a ukáže důvod.</p><div class="fields">${field('Druh akce',`<select id="calendarKind13"><option value="opening">Zahájení přípravy kavárny</option><option value="renovation">Přestavba vlastní kavárny</option><option value="coffee">Uvedení otestované kávy do prodeje</option></select>`)}${field('Týden zahájení',input('calendarDue13',state.stores.length||hasOpeningWork6()?state.week+1:state.week,state.week,state.week+52,1))}${field('Maximální platba v termínu / Kč',input('calendarCap13',250000,0,10000000,500))}${field('Chráněná rezerva / týdny',input('calendarReserve13',3,1,8,1))}</div><div id="calendarOpening13" class="fields">${field('Volná adresa',`<select id="calendarLocation13">${locations.map(l=>option(l.id,l.city+' · '+l.name,'')).join('')}</select>`)}${field('Návrh nové kavárny',`<select id="calendarOpeningDesign13"><option value="starter">Úsporný start</option><option value="base">Základní prostor</option>${state.studio5.designs.map(x=>option(x.id,x.name,'')).join('')}</select>`)}${field('Vedoucí přípravy',`<select id="calendarManager13"><option value="">Vyberu vedoucího později</option>${state.talents.filter(p=>!academyBusy6(p.pid)).map(p=>option(p.pid,p.name,'')).join('')}</select>`)}</div><div id="calendarRenovation13" class="fields" hidden>${field('Vlastní kavárna',`<select id="calendarStore13">${stores.map(s=>option(s.id,loc(s.id).name,'')).join('')}</select>`)}${field('Uložení / styl',`<select id="calendarDesign13"><option value="speed">Rychlá obsluha · současné vybavení</option><option value="lounge">Pohodlné posezení · současné vybavení</option>${state.studio5.designs.map(x=>option(x.id,x.name,'')).join('')}</select>`)}</div><div id="calendarCoffee13" class="fields" hidden>${field('Otestovaná balená káva',`<select id="calendarProduct13">${products.map(p=>option(p.id,p.name,'')).join('')}</select>`)}${field('Skutečná balení / ks',input('calendarUnits13',20,1,2000,1))}${field('Prodejní kanál',`<select id="calendarChannel13">${stores.map(s=>option(s.id,'Kavárna · '+loc(s.id).name,'')).join('')}<option value="eshop">E-shop · funkční IT a projekt</option></select>`)}</div><div class="actions"><button class="primary" id="calendarQuote13">Prověřit akci a souběh</button><button class="soft" id="calendarBack13">Zpět do kalendáře</button></div><p class="sub">Založení zahájí standardní několik týdnů přípravy; nejde o okamžité otevření. Uvedení kávy zaplatí obaly a rozvoz skutečné kávy. Plán zdarma nedrží adresu ani pracovníky.</p>`);el('calendarBack13').onclick=intelligenceHome13;el('calendarKind13').onchange=()=>{const kind=el('calendarKind13').value;el('calendarOpening13').hidden=kind!=='opening';el('calendarRenovation13').hidden=kind!=='renovation';el('calendarCoffee13').hidden=kind!=='coffee';};el('calendarQuote13').onclick=()=>{try{const kind=el('calendarKind13').value;let data;if(kind==='opening'){const design=el('calendarOpeningDesign13').value;data={kind:'cafe',options:{location:el('calendarLocation13').value,design,options:{kind:'legacy',space:'starter'},managerPid:el('calendarManager13').value||undefined}};}else if(kind==='renovation'){const id=el('calendarStore13').value,selected=el('calendarDesign13').value,design=['speed','lounge'].includes(selected)?{...storeDesign5(tnStore7(id)),layout:selected}:state.studio5.designs.find(x=>x.id===selected)?.design;data={id,design};}else{const channel=el('calendarChannel13').value;data={id:el('calendarProduct13').value,units:Number(el('calendarUnits13').value),eshop:channel==='eshop',stores:channel==='eshop'?[]:[channel]};}const due=Number(el('calendarDue13').value),cap=Number(el('calendarCap13').value),reserve=Number(el('calendarReserve13').value),q=scheduleQuote13(kind,data,due,cap,reserve);show(`<h2>${esc(q.title)} · T${q.due}</h2>${rows([['Dnešní odhad platby',money(q.estimate.cost)],['Schválený strop budoucí platby',money(q.cap)],['Změna týdenních závazků',money(q.estimate.weekly)],['Chráněná hotovost při provedení',money(q.estimate.protectedCash)]])}${q.warnings.map(t=>`<p class="warning">${esc(t)}</p>`).join('')}<p>Odehraješ-li T${q.due}, nejprve znovu prověříme cenu a dostupnost. Nyní se nic neplatí. Příprava, držení prostor, nábor a dodávky pokračují samostatně.</p><div class="actions"><button class="primary" id="calendarConfirm13" ${q.estimate.cost>q.cap?'disabled':''}>Schválit plán</button><button class="soft" id="calendarCancel13">Zrušit</button></div>`);el('calendarCancel13').onclick=calendarNewUI13;el('calendarConfirm13').onclick=()=>{const result=act(()=>scheduleAction13(kind,data,due,cap,reserve,q));if(result)intelligenceHome13();};}catch(e){toast(e.message);}};}
function negotiationUI13(pid){const a=staffAssignments().find(a=>a.person.pid===pid),p=a?.person,pending=p&&state.intelligence13.negotiations.find(x=>x.pid===pid&&x.status==='accepted'),g=pending&&pending.goalCreated!==p.career12?.goal?.created?p.career12?.history.find(g=>g.created===pending.goalCreated):p?.career12?.goal;if(!g||g.status!=='active'&&!activeNegotiation13(pid,g)){toast('Není aktuální kariérní cíl ani dohoda.');return;}const current=activeNegotiation13(pid,g);show(`<h2>${esc(p.name)} · vyjednávání</h2><p>${CAREER_FOCUS12[g.focus]} · skutečný cíl ${number(careerGoalValue12(p,g,a),1)} / ${g.target}. Původní termín T${g.due}.</p>${current?`<div class="success">Přijatá dohoda do T${current.due} · zaplacená školení ${current.completedTraining}/${current.training}.</div>${current.completedTraining<current.training?'<button class="primary" id="agreementTrain13">Prověřit slíbené školení</button>':''}`:`<div class="fields">${field('Rozvoj nebo odpovědnost',`<select id="negotiationFocus13">${Object.entries(CAREER_FOCUS12).map(([key,label])=>option(key,label,g.focus)).join('')}</select>`)}${field('Prodloužení / týdny',input('negotiationExtra13',2,0,6,1))}${field('Slíbená skutečná školení',input('negotiationTraining13',g.focus==='region'?0:2,0,g.focus==='region'?0:2,1))}</div><button class="primary" id="negotiationQuote13">Připravit nabídku</button>`}<p class="sub">Dohoda sama nezlepší schopnosti ani neprovede povýšení. Školení zaplatíš ve skutečných kariérních krocích; termín a slib zůstanou v historii.</p><h3>Průběh jednání</h3>${state.intelligence13.negotiations.filter(x=>x.pid===pid).slice().reverse().map(x=>`<p>T${x.created} · ${({accepted:'Přijato',counter:'Protinávrh',rejected:'Odmítnuto',fulfilled:'Splněno',missed:'Nesplněno',unavailable:'Změna působiště'})[x.status]} · termín T${x.due} · ${x.completedTraining}/${x.training} školení${x.counter?' · navrhuje +'+x.counter.extra+' týdnů a '+x.counter.training+' školení':''}</p>${x.status==='counter'&&!current?`<button class="soft" data-counter13="${x.id}">Připravit přijetí protinávrhu</button>`:''}`).join('')||empty('Zatím bez jednání.')}<button class="soft" id="negotiationBack13">Zpět na kariéru</button>`);el('negotiationBack13').onclick=()=>careerPersonUI12(pid);if(el('agreementTrain13'))el('agreementTrain13').onclick=()=>{try{const q=agreementTrainingQuote13(current.id,3);experienceConfirmation12('Zaplatit dohodnuté školení?',money(q.cost)+' za skutečný rozvoj. Chráněná rezerva '+money(q.protectedCash)+'.',()=>payAgreementTraining13(current.id,3,q),()=>negotiationUI13(pid),'Zaplatit školení');el('cancelAction').onclick=()=>negotiationUI13(pid);}catch(e){toast(e.message);}};if(el('negotiationFocus13'))el('negotiationFocus13').onchange=()=>{const region=el('negotiationFocus13').value==='region';el('negotiationTraining13').max=region?0:2;el('negotiationTraining13').value=region?0:2;};const offer=terms=>{try{const q=negotiationQuote13(pid,terms);experienceConfirmation12('Předložit nabídku '+q.name+'?','Prodloužení '+terms.extra+' týdnů a '+terms.training+' skutečně placených školení · '+CAREER_FOCUS12[terms.focus||g.focus]+'. Člověk může odmítnout nebo nabídnout jiné podmínky.',()=>negotiateCareer13(pid,terms,q),()=>negotiationUI13(pid),'Předložit nabídku');el('cancelAction').onclick=()=>negotiationUI13(pid);}catch(e){toast(e.message);}};if(el('negotiationQuote13'))el('negotiationQuote13').onclick=()=>offer({extra:Number(el('negotiationExtra13').value),training:Number(el('negotiationTraining13').value),focus:el('negotiationFocus13').value});on('[data-counter13]',b=>offer(state.intelligence13.negotiations.find(x=>x.id===b.dataset.counter13).counter));}
careerPersonUI12=function(pid){INTELLIGENCE_UI13.careerPersonUI12(pid);const p=staffAssignments().find(a=>a.person.pid===pid)?.person,g=p?.career12?.goal;if(g&&(g.status==='active'||activeNegotiation13(pid,g))){const b=document.createElement('button');b.id='careerNegotiate13';b.className='primary';b.textContent='Vyjednat termín a rozvoj';b.onclick=()=>negotiationUI13(pid);el('modalContent').querySelector('h2').after(b);const agreement=activeNegotiation13(pid,g);if(agreement){const note=document.createElement('p');note.className='warning';note.textContent='Přijatá dohoda do T'+agreement.due+' · školení '+agreement.completedTraining+'/'+agreement.training+'.';b.after(note);}}};
uxAreas11=function(){INTELLIGENCE_UI13.uxAreas11();const b=document.createElement('button');b.id='intelligenceOpen13';b.className='soft';b.textContent='Kalendář a zkušenosti';b.onclick=intelligenceHome13;el('modalContent').querySelector('.ux-utilities11').prepend(b);};
managementView=function(){return `<section class="card"><h2>Kalendář a zkušenosti</h2><p>Naplánované akce, souběh výdajů a doložené učení manažerů.</p><button class="primary" id="intelligenceManage13">Otevřít kalendář firmy</button></section>`+INTELLIGENCE_UI13.managementView();};
rivalDetail5=function(id){INTELLIGENCE_UI13.rivalDetail5(id);const m=rivalMemory13(id),section=document.createElement('section');section.innerHTML=`<h3>Paměť vztahu s tvou firmou</h3><p>Vztah ${rivalRelationship13(id)} · ${rivalRelationship13(id)<=-3?'Pamatuje si střet; více zvažuje místní konkurenci.':rivalRelationship13(id)>=3?'Partnerská spolupráce; dává přednost jiným přínosným investicím.':'Dosud vyrovnaný vztah.'}</p>${m.events.slice().reverse().map(x=>`<p>T${x.week} · ${esc(x.text)}</p>`).join('')||empty('Zatím bez doloženého přestupu nebo obchodní spolupráce.')}<p>${Object.entries(m.wars).filter(([,x])=>x.weeks>=2).map(([city,x])=>esc(city)+' · '+x.weeks+' po sobě jdoucích týdnů cenového tlaku').join('<br>')}</p><p class="sub">Vzpomínky posledních 26 týdnů mění pořadí skutečných investic. Soupeř stále potřebuje kladný odhad přínosu, peníze, rezervu a návratnost.</p>`;el('modalContent').append(section);};
digestDestination6=function(x){if(x.title?.startsWith('Kalendář:')){closeDigest6();intelligenceHome13();return;}if(x.key.startsWith('agreement-')){closeDigest6();negotiationUI13(x.target);return;}if(x.key.startsWith('calendar-')){closeDigest6();intelligenceHome13();return;}return INTELLIGENCE_UI13.digestDestination6(x);};
showDigest6=function(week){INTELLIGENCE_UI13.showDigest6(week);const h=weeklyDigest6(week),root=el('modalContent');if(!h||!el('modal').open)return;const distant=h.items.map(x=>({x,city:x.elsewhere13===undefined?digestElsewhere13(x):x.elsewhere13})).filter(i=>i.city),details=document.createElement('details');details.id='digestElsewhere13';details.className='digest-elsewhere13';details.innerHTML='<summary>Zprávy z ostatních měst · '+distant.length+'</summary>';for(const {x,city} of distant){const b=[...root.querySelectorAll('[data-digest-open6]')].find(b=>b.dataset.digestOpen6===x.key&&!b.hasAttribute('data-weekly-request12')),article=b?.closest('article');if(article){article.dataset.city13=city;details.append(article);}}if(details.querySelector('article')){root.append(details);for(const s of root.querySelectorAll('.digest-section6'))if(s.id!=='weeklyRequests12'){const n=s.querySelectorAll('article').length;if(!n)s.remove();else{const title=s.querySelector('h3');if(title)title.textContent=title.textContent.replace(/ · [0-9]+$/,' · '+n);}}}const note=document.createElement('p');note.className='sub';note.id='digestFocus13';note.textContent='Nejprve tvoje firma a rozhodnutí. Městské zprávy mimo tvoje provozy najdeš v rozbalovací části.';root.querySelector('.digest-overview6').before(note);};
bind=function(){INTELLIGENCE_UI13.bind();if(el('intelligenceManage13'))el('intelligenceManage13').onclick=intelligenceHome13;};
